INSERT INTO rulebook_source_spokes (spoke_id, name, kind, direction, required, purpose, authority)
VALUES ('spoke-001', 'Admin Portal (Postgres editor)', 'admin-portal', 'bidirectional', FALSE, 'Local web UI; edits flow through Postgres for real-time UX, write-through to rulebook JSON on every save. Primary developer experience.', 'Rulebook JSON is durable SSoT; Postgres is the live editor only and can be dropped/rebuilt from JSON at any time.') ON CONFLICT (spoke_id) DO UPDATE SET name = EXCLUDED.name, kind = EXCLUDED.kind, direction = EXCLUDED.direction, required = EXCLUDED.required, purpose = EXCLUDED.purpose, authority = EXCLUDED.authority;

INSERT INTO rulebook_source_spokes (spoke_id, name, kind, direction, required, purpose, authority)
VALUES ('spoke-002', 'Airtable (airtable-to-rulebook)', 'airtable', 'input', FALSE, 'Official Effortless tool: pull schema + data from an Airtable base into the rulebook JSON. Optional input spoke (was the historical HEAD).', 'Rulebook JSON wins; reverse-sync is a separate spoke.') ON CONFLICT (spoke_id) DO UPDATE SET name = EXCLUDED.name, kind = EXCLUDED.kind, direction = EXCLUDED.direction, required = EXCLUDED.required, purpose = EXCLUDED.purpose, authority = EXCLUDED.authority;

INSERT INTO rulebook_source_spokes (spoke_id, name, kind, direction, required, purpose, authority)
VALUES ('spoke-003', 'Reverse Sync (rulebook-to-airtable)', 'reverse-sync', 'output', FALSE, 'Push rulebook JSON edits back to an Airtable base for human review', 'Output only; never reads from Airtable.') ON CONFLICT (spoke_id) DO UPDATE SET name = EXCLUDED.name, kind = EXCLUDED.kind, direction = EXCLUDED.direction, required = EXCLUDED.required, purpose = EXCLUDED.purpose, authority = EXCLUDED.authority;

INSERT INTO rulebook_source_spokes (spoke_id, name, kind, direction, required, purpose, authority)
VALUES ('spoke-004', 'LLM Direct Edits', 'llm-direct', 'input', FALSE, 'Claude / agent edits effortless-rulebook.json directly via filesystem; admin portal reflects changes on reload.', 'Rulebook JSON is the canonical surface for LLM edits.') ON CONFLICT (spoke_id) DO UPDATE SET name = EXCLUDED.name, kind = EXCLUDED.kind, direction = EXCLUDED.direction, required = EXCLUDED.required, purpose = EXCLUDED.purpose, authority = EXCLUDED.authority;

INSERT INTO rulebook_source_spokes (spoke_id, name, kind, direction, required, purpose, authority)
VALUES ('spoke-005', 'Rulebook Cache (offline)', 'airtable', 'input', FALSE, 'Cache of previously-pulled Airtable rulebooks; used when Airtable API unavailable', 'Last-known-good copy; superseded by any newer authoritative pull.') ON CONFLICT (spoke_id) DO UPDATE SET name = EXCLUDED.name, kind = EXCLUDED.kind, direction = EXCLUDED.direction, required = EXCLUDED.required, purpose = EXCLUDED.purpose, authority = EXCLUDED.authority;

INSERT INTO rulebook_source_spokes (spoke_id, name, kind, direction, required, purpose, authority)
VALUES ('spoke-006', 'Manual JSON Edits', 'manual-json', 'input', FALSE, 'Developer hand-edits effortless-rulebook.json in their editor; no special tooling required.', 'Rulebook JSON is the file under version control.') ON CONFLICT (spoke_id) DO UPDATE SET name = EXCLUDED.name, kind = EXCLUDED.kind, direction = EXCLUDED.direction, required = EXCLUDED.required, purpose = EXCLUDED.purpose, authority = EXCLUDED.authority;

-- ----------------------------------------------------------------------------
-- RulebookDomains: Customer ontologies: each domain has its own rulebook + substrate generation. Domains form a TREE — ParentDomainId links a more-elaborate domain back to the simpler one it grew out of (e.g. Talisman ADVANCED ← Talisman BASIC). The UI uses this to present related rulebooks as a set rather than a flat list, and to drive 'next step in the progression' navigation.
-- ----------------------------------------------------------------------------
INSERT INTO rulebook_domains (domain_id, area, is_intentional_exception, domain_name, relative_path, rulebook_path, complexity_level, table_count, key_features, purpose, parent_domain_id, progression_note, project)
VALUES ('domain-root', 'root', FALSE, 'effortless-rulebooks', './', './effortless-rulebook/effortless-rulebook.json', 'platform', 36, 'governing rulebook, generated editor, repository consistency, root explorer programme', 'The repository''s governing Effortless project and promoted platform experience.', NULL, 'Root project: governs and explains every toy, example, skill, rule, finding, and delivery story.', 'erb-001') ON CONFLICT (domain_id) DO UPDATE SET area = EXCLUDED.area, is_intentional_exception = EXCLUDED.is_intentional_exception, domain_name = EXCLUDED.domain_name, relative_path = EXCLUDED.relative_path, rulebook_path = EXCLUDED.rulebook_path, complexity_level = EXCLUDED.complexity_level, table_count = EXCLUDED.table_count, key_features = EXCLUDED.key_features, purpose = EXCLUDED.purpose, parent_domain_id = EXCLUDED.parent_domain_id, progression_note = EXCLUDED.progression_note, project = EXCLUDED.project;

INSERT INTO rulebook_domains (domain_id, area, is_intentional_exception, domain_name, relative_path, rulebook_path, complexity_level, table_count, key_features, purpose, parent_domain_id, progression_note, project)
VALUES ('domain-customer-fullname', 'toy-rulebooks', FALSE, 'Customer FullName', 'toy-rulebooks/customer-fullname/', 'toy-rulebooks/customer-fullname/effortless-rulebook/customer-fullname-rulebook.json', 'minimal', 2, 'string concatenation', 'Hello World: demonstrates basic schema and calculated field (CONCAT formula)', NULL, 'Root of the formula-progression tree: one table, one calculated field, one CONCAT formula. The smallest possible rulebook that still demonstrates the contract.', 'erb-001') ON CONFLICT (domain_id) DO UPDATE SET area = EXCLUDED.area, is_intentional_exception = EXCLUDED.is_intentional_exception, domain_name = EXCLUDED.domain_name, relative_path = EXCLUDED.relative_path, rulebook_path = EXCLUDED.rulebook_path, complexity_level = EXCLUDED.complexity_level, table_count = EXCLUDED.table_count, key_features = EXCLUDED.key_features, purpose = EXCLUDED.purpose, parent_domain_id = EXCLUDED.parent_domain_id, progression_note = EXCLUDED.progression_note, project = EXCLUDED.project;

