VALUES ('domain-effortless-math', 'rulebook-examples', FALSE, 'Effortless Math', 'rulebook-examples/effortless-math/', 'rulebook-examples/effortless-math/effortless-rulebook/effortless-math-rulebook.json', 'advanced', 16, 'provider/consumer theorem contracts, non-boolean proof-status ledger, trust-boundary DAG, versioned certificates, bitemporal witness/provenance', 'Executable theorem network — Fermat''s Last Theorem as flagship consumer over seven imported provider theorems; a certificate/status ledger for a proof network, not a prover.', NULL, 'Points the hub-and-spoke method at mathematics itself: proof status is data (IMPORTED … FULLY_INTERNALIZED_FOR_SCOPE), the trust boundary falls out of the DAG, and it is category-honest — it reproduces the frozen v21 answer key (8 theorems, 7 load-bearing deps, 1 derived contradiction, 0 providers fully internalized) and never claims a zero-import proof of FLT.', 'erb-001') ON CONFLICT (domain_id) DO UPDATE SET area = EXCLUDED.area, is_intentional_exception = EXCLUDED.is_intentional_exception, domain_name = EXCLUDED.domain_name, relative_path = EXCLUDED.relative_path, rulebook_path = EXCLUDED.rulebook_path, complexity_level = EXCLUDED.complexity_level, table_count = EXCLUDED.table_count, key_features = EXCLUDED.key_features, purpose = EXCLUDED.purpose, parent_domain_id = EXCLUDED.parent_domain_id, progression_note = EXCLUDED.progression_note, project = EXCLUDED.project;

