-- ----------------------------------------------------------------------------
-- LegacyRunnerCapabilities: Succession ledger for rulebook-examples/legacy-runner/, a permanent governed example that is no longer privileged. Each row records which platform surface now owns a capability's role (promote / separate / replace) or that it has none (retire). The runner keeps its copy of every capability; nothing is deleted.
-- ----------------------------------------------------------------------------
INSERT INTO legacy_runner_capabilities (legacy_runner_capability_id, title, runner_path, summary, decision, destination, rationale, status, dependents, project)
VALUES ('cap-admin-portal', 'Admin portal', 'admin-portal/', 'Two-rulebook web editor on :7777 with users, roles, navigation, screens and APIs modeled in the runner rulebook.', 'replace', 'Generated effortless-rulebook-editor (:42442, :42441) plus the root explorer (:42440).', 'The generated editor edits any rulebook with zero bespoke code and the explorer covers discovery and guidance; the portal''s overlay contradicts one-rulebook-per-project.', 'done', 'None outside the runner. Root start.sh has no dependency on it (US-052-ac1).', 'erb-001') ON CONFLICT (legacy_runner_capability_id) DO UPDATE SET title = EXCLUDED.title, runner_path = EXCLUDED.runner_path, summary = EXCLUDED.summary, decision = EXCLUDED.decision, destination = EXCLUDED.destination, rationale = EXCLUDED.rationale, status = EXCLUDED.status, dependents = EXCLUDED.dependents, project = EXCLUDED.project;

INSERT INTO legacy_runner_capabilities (legacy_runner_capability_id, title, runner_path, summary, decision, destination, rationale, status, dependents, project)
VALUES ('cap-transpiler-bus', 'ssotme-proxy transpiler bus', 'ssotme-proxy/', 'HTTP server on :4242 exposing 13 repo-local injectors as ssotme:// transpiler routes.', 'replace', 'Its own governed project (working name rulebook-examples/transpiler-bus/) with its own rulebook, README, CLAUDE.md and start.sh; until the move, launch it with rulebook-examples/legacy-runner/ssotme-proxy/start.sh', '26 governed projects have enabled routes on :4242; the CLI is absorbing the bus as infrastructure (Step 12) so no project has to start a server. The runner keeps ssotme-proxy as the legacy bus.', 'decided', '26 child effortless.json files; talismans-special-solutions/postgres-bootstrap/ensure-orchestrator.sh.', 'erb-001') ON CONFLICT (legacy_runner_capability_id) DO UPDATE SET title = EXCLUDED.title, runner_path = EXCLUDED.runner_path, summary = EXCLUDED.summary, decision = EXCLUDED.decision, destination = EXCLUDED.destination, rationale = EXCLUDED.rationale, status = EXCLUDED.status, dependents = EXCLUDED.dependents, project = EXCLUDED.project;

INSERT INTO legacy_runner_capabilities (legacy_runner_capability_id, title, runner_path, summary, decision, destination, rationale, status, dependents, project)
VALUES ('cap-execution-substrates', 'Execution substrates (injectors)', 'execution-substrates/', 'Python, Go, COBOL, binary, CSV, XLSX, UML, OWL, English, explain-DAG, Airtable and postgres-calculated-to-rulebook injectors plus take-test harnesses.', 'replace', 'Its own governed project (working name rulebook-examples/transpiler-bus/) with its own rulebook, README, CLAUDE.md and start.sh; until the move, launch it with rulebook-examples/legacy-runner/ssotme-proxy/start.sh', 'Each inject-into-<technology>.py maps one-to-one onto a Step 12 script tool (EFFORTLESS_INPUT_DIR / EFFORTLESS_OUTPUT_DIR). The runner keeps the injectors and the menu that drives them.', 'decided', 'ssotme-proxy/server.py TRANSPILERS table; orchestration/test-orchestrator.py.', 'erb-001') ON CONFLICT (legacy_runner_capability_id) DO UPDATE SET title = EXCLUDED.title, runner_path = EXCLUDED.runner_path, summary = EXCLUDED.summary, decision = EXCLUDED.decision, destination = EXCLUDED.destination, rationale = EXCLUDED.rationale, status = EXCLUDED.status, dependents = EXCLUDED.dependents, project = EXCLUDED.project;

INSERT INTO legacy_runner_capabilities (legacy_runner_capability_id, title, runner_path, summary, decision, destination, rationale, status, dependents, project)
VALUES ('cap-formula-core', 'Shared formula parser and utilities', 'orchestration/shared.py, orchestration/formula_parser.py', 'Rulebook loading, candidate resolution and the Excel-dialect formula parser every injector imports.', 'replace', 'Its own governed project (working name rulebook-examples/transpiler-bus/) with its own rulebook, README, CLAUDE.md and start.sh; until the move, launch it with rulebook-examples/legacy-runner/ssotme-proxy/start.sh', 'Travels with the injectors that import it. The runner keeps its copy.', 'decided', '42 files under execution-substrates/; ssotme-proxy/server.py.', 'erb-001') ON CONFLICT (legacy_runner_capability_id) DO UPDATE SET title = EXCLUDED.title, runner_path = EXCLUDED.runner_path, summary = EXCLUDED.summary, decision = EXCLUDED.decision, destination = EXCLUDED.destination, rationale = EXCLUDED.rationale, status = EXCLUDED.status, dependents = EXCLUDED.dependents, project = EXCLUDED.project;

INSERT INTO legacy_runner_capabilities (legacy_runner_capability_id, title, runner_path, summary, decision, destination, rationale, status, dependents, project)
VALUES ('cap-conformance-harness', 'Conformance harness and reports', 'testing/, orchestration/test-orchestrator.py, orchestration/grade-and-record.py, orchestration/generate-report.py, orchestration/llm-fuzzy-grader.py', 'Blank tests, answer keys, per-substrate grading, fuzzy LLM grading and the substrate-equivalence report.', 'promote', 'Conformance results as first-class rows in the root rulebook, displayed by the root explorer the way slot witnesses are; the runner keeps the harness and its report as the legacy view.', 'Orchestration is what the explorer does visually: pick a project, build it, see every substrate graded. The harness stays runnable in the runner and its results become data the explorer shows.', 'decided', 'take-test.sh in every substrate; SubstrateContractPhases / EvaluationSteps rows in the runner rulebook.', 'erb-001') ON CONFLICT (legacy_runner_capability_id) DO UPDATE SET title = EXCLUDED.title, runner_path = EXCLUDED.runner_path, summary = EXCLUDED.summary, decision = EXCLUDED.decision, destination = EXCLUDED.destination, rationale = EXCLUDED.rationale, status = EXCLUDED.status, dependents = EXCLUDED.dependents, project = EXCLUDED.project;

INSERT INTO legacy_runner_capabilities (legacy_runner_capability_id, title, runner_path, summary, decision, destination, rationale, status, dependents, project)
VALUES ('cap-cli-menu', 'CLI orchestration menu', 'start.sh, orchestration/orchestrate.sh, run-web-portal.sh, run-in-docker.sh, docker-compose.yml, Dockerfile', 'Interactive menu that picks an active domain, builds it, runs substrates and launches the portal.', 'replace', 'Root explorer (:42440) plus per-project ./start.sh for the platform role; the runner keeps the menu as its own experience (./start.sh here launches it).', 'Every governed project owns its start and the explorer shows what the menu showed. The menu remains the legacy way to run the same pipeline.', 'done', 'None outside the runner.', 'erb-001') ON CONFLICT (legacy_runner_capability_id) DO UPDATE SET title = EXCLUDED.title, runner_path = EXCLUDED.runner_path, summary = EXCLUDED.summary, decision = EXCLUDED.decision, destination = EXCLUDED.destination, rationale = EXCLUDED.rationale, status = EXCLUDED.status, dependents = EXCLUDED.dependents, project = EXCLUDED.project;

INSERT INTO legacy_runner_capabilities (legacy_runner_capability_id, title, runner_path, summary, decision, destination, rationale, status, dependents, project)
VALUES ('cap-build-all', 'Cross-project build tooling', 'orchestration/build-all-domains.sh, orchestration/build-status-report.py, devops/buildall.sh', 'Loops over every domain running effortless build and writes a status report.', 'replace', 'scripts/scan-project-slots.py with ProjectSlotWitnesses / ConsistencyFindings views and the generated progress report.', 'Repository status is now derived from witnessed slots and finding rows rather than a build loop''s log.', 'done', 'None.', 'erb-001') ON CONFLICT (legacy_runner_capability_id) DO UPDATE SET title = EXCLUDED.title, runner_path = EXCLUDED.runner_path, summary = EXCLUDED.summary, decision = EXCLUDED.decision, destination = EXCLUDED.destination, rationale = EXCLUDED.rationale, status = EXCLUDED.status, dependents = EXCLUDED.dependents, project = EXCLUDED.project;

