INSERT INTO legacy_runner_capabilities (legacy_runner_capability_id, title, runner_path, summary, decision, destination, rationale, status, dependents, project)
VALUES ('cap-devops', 'Devops scripts', 'devops/pull.sh, devops/rebuild-on-trigger.sh, devops/last-payload.json', 'Pull-and-rebuild hooks for the old hosted runner.', 'retire', 'Root ./start.sh owns restart; the editor container owns rebuild via /tmp/rebuild-trigger.', 'The hosted runner no longer exists; the root''s launch contract covers restart and rebuild.', 'done', 'None.', 'erb-001') ON CONFLICT (legacy_runner_capability_id) DO UPDATE SET title = EXCLUDED.title, runner_path = EXCLUDED.runner_path, summary = EXCLUDED.summary, decision = EXCLUDED.decision, destination = EXCLUDED.destination, rationale = EXCLUDED.rationale, status = EXCLUDED.status, dependents = EXCLUDED.dependents, project = EXCLUDED.project;

