VALUES ('cap-docs-transpiler', 'Platform docs transpiler', 'transpilers/platform-rulebook-to-docs.py, docs/generate-rulebook-md.hbars, JsonHbarsTransform step', 'Hand-written Python and Handlebars that rendered the platform rulebook to Markdown.', 'replace', 'rulebook-to-rulespeak, rulebook-to-progress-report and the root explorer, all registered in the root effortless.json.', 'Bespoke doc generation duplicated what published transpilers now emit from the same rulebook.', 'done', 'Runner effortless.json only.', 'erb-001') ON CONFLICT (legacy_runner_capability_id) DO UPDATE SET title = EXCLUDED.title, runner_path = EXCLUDED.runner_path, summary = EXCLUDED.summary, decision = EXCLUDED.decision, destination = EXCLUDED.destination, rationale = EXCLUDED.rationale, status = EXCLUDED.status, dependents = EXCLUDED.dependents, project = EXCLUDED.project;

