VALUES ('glo-no-fallback-rule', 'No Fallback Rule', 'invariant', 'Repo-wide policy: if a file is missing, fail loudly with the exact expected path. No silent path-guessing, no try/except that swallows missing files. Defaults derived deterministically from the SSoT are not fallbacks.', 'file:CLAUDE.md (NEVER ADD FALLBACKS section)', NULL, NULL) ON CONFLICT (term_id) DO UPDATE SET term = EXCLUDED.term, category = EXCLUDED.category, definition = EXCLUDED.definition, implemented_as = EXCLUDED.implemented_as, aliases = EXCLUDED.aliases, notes = EXCLUDED.notes;

INSERT INTO glossary (term_id, term, category, definition, implemented_as, aliases, notes)
VALUES ('glo-rulebook-promotion', 'Rulebook Promotion', 'concept', 'The architectural decision to promote effortless-rulebook.json from disposable IR to durable hub/SSoT, demoting Airtable from authority to peer input spoke. Largely complete.', 'axiom:ax-004; file:LEGACY_PLANs/RULEBOOK_PROMOTION_PLAN.md', NULL, NULL) ON CONFLICT (term_id) DO UPDATE SET term = EXCLUDED.term, category = EXCLUDED.category, definition = EXCLUDED.definition, implemented_as = EXCLUDED.implemented_as, aliases = EXCLUDED.aliases, notes = EXCLUDED.notes;

