-- ----------------------------------------------------------------------------
-- ClaudeSkills: The catalog of Claude Code skills that make up the effortless-claude skill set. Each skill is a loadable instruction set that pre-teaches Claude everything it needs to work in an ERB project — naming conventions, pipeline mechanics, formula semantics, etc. Skills are the answer to the LLM learning-curve problem: instead of every user teaching Claude from scratch, the learning is encoded once and loaded on demand. LocalMirrorPath is a derived artifact: clone-skills.sh pulls a live copy of each skill from the source repo so the docs/skills/ mirror stays current.
-- ----------------------------------------------------------------------------
INSERT INTO claude_skills (skill_id, name, category, load_gate, is_entry_point, status, one_line_summary, audience, clone_url, highlight_in_readme, project)
VALUES ('effortless-airtable', 'effortless-airtable', 'data', 'effortless-project', FALSE, 'active', 'Use when making schema or data changes via the Airtable API in an ERB project — adding fields, creating tables, modifying existing fields, or when you need to understand Airtable API limitations (e.', 'customer', 'https://raw.githubusercontent.com/effortlessapi/effortless-claude/main/skills/effortless-airtable/SKILL.md', FALSE, 'erb-001') ON CONFLICT (skill_id) DO UPDATE SET name = EXCLUDED.name, category = EXCLUDED.category, load_gate = EXCLUDED.load_gate, is_entry_point = EXCLUDED.is_entry_point, status = EXCLUDED.status, one_line_summary = EXCLUDED.one_line_summary, audience = EXCLUDED.audience, clone_url = EXCLUDED.clone_url, highlight_in_readme = EXCLUDED.highlight_in_readme, project = EXCLUDED.project;

INSERT INTO claude_skills (skill_id, name, category, load_gate, is_entry_point, status, one_line_summary, audience, clone_url, highlight_in_readme, project)
VALUES ('effortless-airtable-omni', 'effortless-airtable-omni', 'data', 'effortless-project', FALSE, 'active', 'Use ONLY for Airtable schema changes that the API cannot handle — formula fields, lookup fields, rollup fields, and new table creation (which requires the Name formula).', 'customer', 'https://raw.githubusercontent.com/effortlessapi/effortless-claude/main/skills/effortless-airtable-omni/SKILL.md', FALSE, 'erb-001') ON CONFLICT (skill_id) DO UPDATE SET name = EXCLUDED.name, category = EXCLUDED.category, load_gate = EXCLUDED.load_gate, is_entry_point = EXCLUDED.is_entry_point, status = EXCLUDED.status, one_line_summary = EXCLUDED.one_line_summary, audience = EXCLUDED.audience, clone_url = EXCLUDED.clone_url, highlight_in_readme = EXCLUDED.highlight_in_readme, project = EXCLUDED.project;

