INSERT INTO user_stories (user_story_id, req_id, story_text, build_phase, epic, feature, effort_class, status, dev_progress_percent)
VALUES ('us-001', 'US-001', 'As a platform maintainer, I want every project directory under rulebook-examples/ and toy-rulebooks/ modeled as a RulebookDomains row keyed by its slug, so the catalog and the filesystem can never silently diverge.', 'phase-1', 'cat-semantic-inventory', 'feat-domain-registry', 'G2', 'done', 100) ON CONFLICT (user_story_id) DO UPDATE SET req_id = EXCLUDED.req_id, story_text = EXCLUDED.story_text, build_phase = EXCLUDED.build_phase, epic = EXCLUDED.epic, feature = EXCLUDED.feature, effort_class = EXCLUDED.effort_class, status = EXCLUDED.status, dev_progress_percent = EXCLUDED.dev_progress_percent;

INSERT INTO user_stories (user_story_id, req_id, story_text, build_phase, epic, feature, effort_class, status, dev_progress_percent)
VALUES ('us-002', 'US-002', 'As a demo author, I want each domain row to carry its actual rulebook path and table count, so stale documentation references are queryable facts instead of folklore.', 'phase-1', 'cat-semantic-inventory', 'feat-domain-registry', 'G1', 'done', 100) ON CONFLICT (user_story_id) DO UPDATE SET req_id = EXCLUDED.req_id, story_text = EXCLUDED.story_text, build_phase = EXCLUDED.build_phase, epic = EXCLUDED.epic, feature = EXCLUDED.feature, effort_class = EXCLUDED.effort_class, status = EXCLUDED.status, dev_progress_percent = EXCLUDED.dev_progress_percent;

INSERT INTO user_stories (user_story_id, req_id, story_text, build_phase, epic, feature, effort_class, status, dev_progress_percent)
VALUES ('us-003', 'US-003', 'As a platform maintainer, I want substrates, proxy routes, transpiler tools, skills, glossary terms, axioms and framing invariants each in a first-class table, so every semantic concept in the repo has exactly one home.', 'phase-1', 'cat-semantic-inventory', 'feat-concept-tables', 'G2', 'done', 100) ON CONFLICT (user_story_id) DO UPDATE SET req_id = EXCLUDED.req_id, story_text = EXCLUDED.story_text, build_phase = EXCLUDED.build_phase, epic = EXCLUDED.epic, feature = EXCLUDED.feature, effort_class = EXCLUDED.effort_class, status = EXCLUDED.status, dev_progress_percent = EXCLUDED.dev_progress_percent;

INSERT INTO user_stories (user_story_id, req_id, story_text, build_phase, epic, feature, effort_class, status, dev_progress_percent)
VALUES ('us-004', 'US-004', 'As an agent working the repo, I want the skill catalog reconciled to the installed skill set including deprecations, so routing decisions come from data, not memory.', 'phase-1', 'cat-semantic-inventory', 'feat-concept-tables', 'G1', 'done', 100) ON CONFLICT (user_story_id) DO UPDATE SET req_id = EXCLUDED.req_id, story_text = EXCLUDED.story_text, build_phase = EXCLUDED.build_phase, epic = EXCLUDED.epic, feature = EXCLUDED.feature, effort_class = EXCLUDED.effort_class, status = EXCLUDED.status, dev_progress_percent = EXCLUDED.dev_progress_percent;

