-- ----------------------------------------------------------------------------
-- ConsistencyRules: Repo-wide consistency invariants as data. Each row is a checkable rule with a fix playbook; ConsistencyFindings rows are its violations.
-- ----------------------------------------------------------------------------
INSERT INTO consistency_rules (consistency_rule_id, rule_code, severity, scope, statement, check_mechanism, fix_playbook, source_doctrine, project)
VALUES ('cr-01', 'canonical-rulebook-path', 'major', 'demo', 'Every project''s rulebook lives directly in <project>/effortless-rulebook/, named either effortless-rulebook.json or <slug>-rulebook.json (both valid; the protocol does not dictate one).', 'Compare RulebookDomains.RulebookPath against RelativePath + "effortless-rulebook/" + either accepted filename (RulebookDomains.IsStandardLayout).', 'git mv the file into effortless-rulebook/ under either accepted name; update effortless.json -i/-o arguments; rebuild.', 'CLAUDE.md § Two categorically different kinds of rulebooks', 'erb-001') ON CONFLICT (consistency_rule_id) DO UPDATE SET rule_code = EXCLUDED.rule_code, severity = EXCLUDED.severity, scope = EXCLUDED.scope, statement = EXCLUDED.statement, check_mechanism = EXCLUDED.check_mechanism, fix_playbook = EXCLUDED.fix_playbook, source_doctrine = EXCLUDED.source_doctrine, project = EXCLUDED.project;

INSERT INTO consistency_rules (consistency_rule_id, rule_code, severity, scope, statement, check_mechanism, fix_playbook, source_doctrine, project)
VALUES ('cr-02', 'effortless-json-present', 'major', 'demo', 'Every project directory carries a real effortless.json build configuration.', 'test -f <project>/effortless.json and confirm it has a ProjectTranspilers array.', 'effortless -init from the project root, then register transpilers with effortless -install.', 'effortless-init skill', 'erb-001') ON CONFLICT (consistency_rule_id) DO UPDATE SET rule_code = EXCLUDED.rule_code, severity = EXCLUDED.severity, scope = EXCLUDED.scope, statement = EXCLUDED.statement, check_mechanism = EXCLUDED.check_mechanism, fix_playbook = EXCLUDED.fix_playbook, source_doctrine = EXCLUDED.source_doctrine, project = EXCLUDED.project;

INSERT INTO consistency_rules (consistency_rule_id, rule_code, severity, scope, statement, check_mechanism, fix_playbook, source_doctrine, project)
VALUES ('cr-03', 'rulespeak-registered', 'major', 'demo', 'Every demo effortless.json includes a rulebooktorulespeak ProjectTranspilers entry.', 'jq ''.ProjectTranspilers[].Name'' effortless.json | grep rulebooktorulespeak', 'cd rulespeak && effortless -install rulebook-to-rulespeak -i ../effortless-rulebook/<slug>-rulebook.json', 'CLAUDE.md § Required transpilers for every new example project', 'erb-001') ON CONFLICT (consistency_rule_id) DO UPDATE SET rule_code = EXCLUDED.rule_code, severity = EXCLUDED.severity, scope = EXCLUDED.scope, statement = EXCLUDED.statement, check_mechanism = EXCLUDED.check_mechanism, fix_playbook = EXCLUDED.fix_playbook, source_doctrine = EXCLUDED.source_doctrine, project = EXCLUDED.project;

INSERT INTO consistency_rules (consistency_rule_id, rule_code, severity, scope, statement, check_mechanism, fix_playbook, source_doctrine, project)
VALUES ('cr-04', 'readme-present', 'minor', 'demo', 'Every project directory has a README.md.', 'test -f <project>/README.md', 'Write a README: purpose, layout, how to build, then the bus section.', 'CLAUDE.md § Required "Local transpiler bus" pointer', 'erb-001') ON CONFLICT (consistency_rule_id) DO UPDATE SET rule_code = EXCLUDED.rule_code, severity = EXCLUDED.severity, scope = EXCLUDED.scope, statement = EXCLUDED.statement, check_mechanism = EXCLUDED.check_mechanism, fix_playbook = EXCLUDED.fix_playbook, source_doctrine = EXCLUDED.source_doctrine, project = EXCLUDED.project;

INSERT INTO consistency_rules (consistency_rule_id, rule_code, severity, scope, statement, check_mechanism, fix_playbook, source_doctrine, project)
VALUES ('cr-05', 'readme-bus-section', 'minor', 'demo', 'Every README ends with the "## Local transpiler bus (`localhost:4242`)" section with the current transpiler count.', 'tail README.md | grep "Local transpiler bus"', 'Append the canonical block from CLAUDE.md.', 'CLAUDE.md § Required "Local transpiler bus" pointer', 'erb-001') ON CONFLICT (consistency_rule_id) DO UPDATE SET rule_code = EXCLUDED.rule_code, severity = EXCLUDED.severity, scope = EXCLUDED.scope, statement = EXCLUDED.statement, check_mechanism = EXCLUDED.check_mechanism, fix_playbook = EXCLUDED.fix_playbook, source_doctrine = EXCLUDED.source_doctrine, project = EXCLUDED.project;

INSERT INTO consistency_rules (consistency_rule_id, rule_code, severity, scope, statement, check_mechanism, fix_playbook, source_doctrine, project)
VALUES ('cr-06', 'meta-table-present', 'major', 'demo', 'Every rulebook carries a typed-row __meta__ table and no project metadata outside it.', 'jq ''has("__meta__")'' <rulebook>', 'python3 orchestration/migrate-meta-to-table.py <rulebook>', 'CLAUDE.md § __meta__ table doctrine', 'erb-001') ON CONFLICT (consistency_rule_id) DO UPDATE SET rule_code = EXCLUDED.rule_code, severity = EXCLUDED.severity, scope = EXCLUDED.scope, statement = EXCLUDED.statement, check_mechanism = EXCLUDED.check_mechanism, fix_playbook = EXCLUDED.fix_playbook, source_doctrine = EXCLUDED.source_doctrine, project = EXCLUDED.project;

INSERT INTO consistency_rules (consistency_rule_id, rule_code, severity, scope, statement, check_mechanism, fix_playbook, source_doctrine, project)
VALUES ('cr-07', 'single-hub-per-project', 'critical', 'demo', 'Exactly one rulebook JSON is the hub of a project; no duplicate copies at other paths.', 'find <project> -name "*rulebook*.json" -not -path "*/node_modules/*" | wc -l == 1 (derived files excepted)', 'Delete the copy that effortless.json does not reference.', 'CLAUDE.md § Authoritative Source: rulebook JSON is HEAD', 'erb-001') ON CONFLICT (consistency_rule_id) DO UPDATE SET rule_code = EXCLUDED.rule_code, severity = EXCLUDED.severity, scope = EXCLUDED.scope, statement = EXCLUDED.statement, check_mechanism = EXCLUDED.check_mechanism, fix_playbook = EXCLUDED.fix_playbook, source_doctrine = EXCLUDED.source_doctrine, project = EXCLUDED.project;

INSERT INTO consistency_rules (consistency_rule_id, rule_code, severity, scope, statement, check_mechanism, fix_playbook, source_doctrine, project)
VALUES ('cr-08', 'no-committed-scratch', 'minor', 'demo', 'No scratch/build artifacts (.bak, __pycache__, node_modules, *.log, lockfiles without manifests) are tracked in git.', 'git ls-files <project> | grep -E "\.bak$|__pycache__|node_modules|\.log$"', 'git rm --cached and add to .gitignore.', 'Repo hygiene', 'erb-001') ON CONFLICT (consistency_rule_id) DO UPDATE SET rule_code = EXCLUDED.rule_code, severity = EXCLUDED.severity, scope = EXCLUDED.scope, statement = EXCLUDED.statement, check_mechanism = EXCLUDED.check_mechanism, fix_playbook = EXCLUDED.fix_playbook, source_doctrine = EXCLUDED.source_doctrine, project = EXCLUDED.project;

INSERT INTO consistency_rules (consistency_rule_id, rule_code, severity, scope, statement, check_mechanism, fix_playbook, source_doctrine, project)
VALUES ('cr-09', 'no-nested-git', 'critical', 'demo', 'No project directory is its own git repository.', 'find . -mindepth 2 -name .git -type d', 'Remove the nested .git (archive history if needed) so the monorepo tracks the files.', 'Repo hygiene', 'erb-001') ON CONFLICT (consistency_rule_id) DO UPDATE SET rule_code = EXCLUDED.rule_code, severity = EXCLUDED.severity, scope = EXCLUDED.scope, statement = EXCLUDED.statement, check_mechanism = EXCLUDED.check_mechanism, fix_playbook = EXCLUDED.fix_playbook, source_doctrine = EXCLUDED.source_doctrine, project = EXCLUDED.project;

INSERT INTO consistency_rules (consistency_rule_id, rule_code, severity, scope, statement, check_mechanism, fix_playbook, source_doctrine, project)
VALUES ('cr-10', 'unique-transpiler-names', 'major', 'demo', 'Within one effortless.json, every ProjectTranspilers entry has a unique Name.', 'jq ''.ProjectTranspilers[].Name'' | sort | uniq -d', 'Rename the duplicate (e.g. rulebooktorulespeakde, execute-2).', 'effortless-ssotme-protocol skill', 'erb-001') ON CONFLICT (consistency_rule_id) DO UPDATE SET rule_code = EXCLUDED.rule_code, severity = EXCLUDED.severity, scope = EXCLUDED.scope, statement = EXCLUDED.statement, check_mechanism = EXCLUDED.check_mechanism, fix_playbook = EXCLUDED.fix_playbook, source_doctrine = EXCLUDED.source_doctrine, project = EXCLUDED.project;

INSERT INTO consistency_rules (consistency_rule_id, rule_code, severity, scope, statement, check_mechanism, fix_playbook, source_doctrine, project)
VALUES ('cr-11', 'no-legacy-ssotme-json', 'minor', 'demo', 'Legacy ssotme.json files are retired in favor of effortless.json.', 'test ! -f <project>/ssotme.json', 'Merge entries into effortless.json and delete ssotme.json.', 'effortless-cli skill', 'erb-001') ON CONFLICT (consistency_rule_id) DO UPDATE SET rule_code = EXCLUDED.rule_code, severity = EXCLUDED.severity, scope = EXCLUDED.scope, statement = EXCLUDED.statement, check_mechanism = EXCLUDED.check_mechanism, fix_playbook = EXCLUDED.fix_playbook, source_doctrine = EXCLUDED.source_doctrine, project = EXCLUDED.project;

INSERT INTO consistency_rules (consistency_rule_id, rule_code, severity, scope, statement, check_mechanism, fix_playbook, source_doctrine, project)
VALUES ('cr-12', 'rulebook-top-level-keys', 'major', 'demo', 'Every rulebook has $schema, Name and Description top-level keys (no legacy model_name).', 'jq ''has("$schema") and has("Name") and has("Description")'' <rulebook>', 'Add the keys; rename model_name to Name.', 'effortless-schema skill', 'erb-001') ON CONFLICT (consistency_rule_id) DO UPDATE SET rule_code = EXCLUDED.rule_code, severity = EXCLUDED.severity, scope = EXCLUDED.scope, statement = EXCLUDED.statement, check_mechanism = EXCLUDED.check_mechanism, fix_playbook = EXCLUDED.fix_playbook, source_doctrine = EXCLUDED.source_doctrine, project = EXCLUDED.project;

INSERT INTO consistency_rules (consistency_rule_id, rule_code, severity, scope, statement, check_mechanism, fix_playbook, source_doctrine, project)
VALUES ('cr-13', 'transpiler-name-conventions', 'minor', 'demo', 'Transpiler Names are the squashed canonical form of the tool name with no typos.', 'Review Names against the tool catalog.', 'Re-register with effortless -install so the CLI writes the canonical Name.', 'effortless-ssotme-protocol skill', 'erb-001') ON CONFLICT (consistency_rule_id) DO UPDATE SET rule_code = EXCLUDED.rule_code, severity = EXCLUDED.severity, scope = EXCLUDED.scope, statement = EXCLUDED.statement, check_mechanism = EXCLUDED.check_mechanism, fix_playbook = EXCLUDED.fix_playbook, source_doctrine = EXCLUDED.source_doctrine, project = EXCLUDED.project;

INSERT INTO consistency_rules (consistency_rule_id, rule_code, severity, scope, statement, check_mechanism, fix_playbook, source_doctrine, project)
VALUES ('cr-14', 'doctrine-matches-filesystem', 'major', 'repo', 'CLAUDE.md and README doctrine cite only paths and projects that exist.', 'grep cited paths in CLAUDE.md against RulebookDomains.RelativePath.', 'Edit the doctrine file to the current layout.', 'CLAUDE.md', 'erb-001') ON CONFLICT (consistency_rule_id) DO UPDATE SET rule_code = EXCLUDED.rule_code, severity = EXCLUDED.severity, scope = EXCLUDED.scope, statement = EXCLUDED.statement, check_mechanism = EXCLUDED.check_mechanism, fix_playbook = EXCLUDED.fix_playbook, source_doctrine = EXCLUDED.source_doctrine, project = EXCLUDED.project;

INSERT INTO consistency_rules (consistency_rule_id, rule_code, severity, scope, statement, check_mechanism, fix_playbook, source_doctrine, project)
VALUES ('cr-15', 'platform-rulebook-integrity', 'major', 'platform', 'Every reference inside the platform rulebook resolves: FK values exist, catalog rows describe things that exist, formulas use the canonical dialect.', 'scratch validator (FK integrity + cycle + formula-dialect checks) run before every build; to be promoted into orchestration/.', 'Repoint or null the reference, record the reason in the field Description, and mark the finding fixed.', 'CLAUDE.md § Avoid Silent Fallbacks', 'erb-001') ON CONFLICT (consistency_rule_id) DO UPDATE SET rule_code = EXCLUDED.rule_code, severity = EXCLUDED.severity, scope = EXCLUDED.scope, statement = EXCLUDED.statement, check_mechanism = EXCLUDED.check_mechanism, fix_playbook = EXCLUDED.fix_playbook, source_doctrine = EXCLUDED.source_doctrine, project = EXCLUDED.project;

INSERT INTO consistency_rules (consistency_rule_id, rule_code, severity, scope, statement, check_mechanism, fix_playbook, source_doctrine, project)
VALUES ('cr-16', 'transpiler-versions-live', 'critical', 'platform', 'Every transpiler a build depends on resolves to a live tool: no pins to decommissioned hosts, and every tool in the pipeline is published as [latest] on the tools server.', 'effortless build must reach every transpiler without Host-not-found retries; compare PinnedVersion/LastUrl in effortless.json against effortless listToolUrls.', 'Remove the stale pin (demos run rulebook-to-postgres at [latest]); publish the missing tool with scripts/publish-tool.sh; until then run it locally and effortless -setToolUrl to localhost.', '~/.claude/CLAUDE.md § Publishing an ssotme / effortless transpiler tool', 'erb-001') ON CONFLICT (consistency_rule_id) DO UPDATE SET rule_code = EXCLUDED.rule_code, severity = EXCLUDED.severity, scope = EXCLUDED.scope, statement = EXCLUDED.statement, check_mechanism = EXCLUDED.check_mechanism, fix_playbook = EXCLUDED.fix_playbook, source_doctrine = EXCLUDED.source_doctrine, project = EXCLUDED.project;

INSERT INTO consistency_rules (consistency_rule_id, rule_code, severity, scope, statement, check_mechanism, fix_playbook, source_doctrine, project)
VALUES ('cr-17', 'universal-start-contract', 'major', 'repo', 'The root and every governed toy/example have one executable ./start.sh that fails loudly, cleanly restarts its intended experience, and prints declared localhost URLs.', 'ProjectSlotWitnesses records executable start.sh presence plus bash syntax, declared-port restart behavior, modeled URL declarations, and explicit health contracts.', 'Add or repair the project''s explicit start.sh; do not probe legacy paths or substitute another project''s experience.', 'PLATFORM-EXPLORER-PLAN.md § ./start.sh: the universal launch contract', 'erb-001') ON CONFLICT (consistency_rule_id) DO UPDATE SET rule_code = EXCLUDED.rule_code, severity = EXCLUDED.severity, scope = EXCLUDED.scope, statement = EXCLUDED.statement, check_mechanism = EXCLUDED.check_mechanism, fix_playbook = EXCLUDED.fix_playbook, source_doctrine = EXCLUDED.source_doctrine, project = EXCLUDED.project;

INSERT INTO consistency_rules (consistency_rule_id, rule_code, severity, scope, statement, check_mechanism, fix_playbook, source_doctrine, project)
VALUES ('cr-18', 'legacy-runner-retirement', 'major', 'platform', 'The promoted root platform has no runtime dependency on the legacy portal or two-rulebook overlay, and every runner capability the platform still needs names its successor surface.', 'Inventory runner capabilities and search root runtime/config/documentation references; every match has a recorded promote, separate, replace, or retire decision.', 'Record the successor in LegacyRunnerCapabilities (root, standalone tool, generated or CLI surface) and point documentation at it. The runner keeps its copy; never delete runner files to satisfy this rule.', 'PLATFORM-EXPLORER-PLAN.md § Legacy-runner retirement', 'erb-001') ON CONFLICT (consistency_rule_id) DO UPDATE SET rule_code = EXCLUDED.rule_code, severity = EXCLUDED.severity, scope = EXCLUDED.scope, statement = EXCLUDED.statement, check_mechanism = EXCLUDED.check_mechanism, fix_playbook = EXCLUDED.fix_playbook, source_doctrine = EXCLUDED.source_doctrine, project = EXCLUDED.project;

INSERT INTO consistency_rules (consistency_rule_id, rule_code, severity, scope, statement, check_mechanism, fix_playbook, source_doctrine, project)
VALUES ('cr-19', 'canonical-project-shape', 'major', 'repo', 'Every governed root, toy, and example fills the canonical slots required for its project kind, as witnessed from disk and effortless.json.', 'scripts/scan-project-slots.py refreshes ProjectSlotWitnesses; vw_rulebook_domains.required_gap_count must be zero.', 'Satisfy the missing explicit slot or correct the governing model; never substitute a legacy path or inferred success.', 'PLATFORM-EXPLORER-PLAN.md § Canonical consistency contract', 'erb-001') ON CONFLICT (consistency_rule_id) DO UPDATE SET rule_code = EXCLUDED.rule_code, severity = EXCLUDED.severity, scope = EXCLUDED.scope, statement = EXCLUDED.statement, check_mechanism = EXCLUDED.check_mechanism, fix_playbook = EXCLUDED.fix_playbook, source_doctrine = EXCLUDED.source_doctrine, project = EXCLUDED.project;

