INSERT INTO consistency_findings (consistency_finding_id, rule, domain, detail, status, detected_on)
VALUES ('cr-16-01', 'cr-16', 'domain-legacy-runner', 'effortless-platform/effortless.json pinned rulebooktopostgres to v2026.04.19.1717 whose cpln host no longer exists; every platform build failed at step one. Unpinned to [latest] like every demo.', 'fixed', '2026-08-30') ON CONFLICT (consistency_finding_id) DO UPDATE SET rule = EXCLUDED.rule, domain = EXCLUDED.domain, detail = EXCLUDED.detail, status = EXCLUDED.status, detected_on = EXCLUDED.detected_on;

INSERT INTO consistency_findings (consistency_finding_id, rule, domain, detail, status, detected_on)
VALUES ('cr-16-02', 'cr-16', NULL, 'rulebook-to-progress-report is not resolvable by bare name and its cpln workloads (v2026.08.29.2158 / .1949) do not answer; the platform pipeline currently depends on a local run on :30052 via effortless -setToolUrl.', 'open', '2026-08-30') ON CONFLICT (consistency_finding_id) DO UPDATE SET rule = EXCLUDED.rule, domain = EXCLUDED.domain, detail = EXCLUDED.detail, status = EXCLUDED.status, detected_on = EXCLUDED.detected_on;

INSERT INTO consistency_findings (consistency_finding_id, rule, domain, detail, status, detected_on)
VALUES ('cr-16-03', 'cr-16', NULL, 'clone-skills cannot mirror effortless-progress-report: the skill exists in the local effortless-skills repo but is not yet in the public effortless-claude skills repo.', 'open', '2026-08-30') ON CONFLICT (consistency_finding_id) DO UPDATE SET rule = EXCLUDED.rule, domain = EXCLUDED.domain, detail = EXCLUDED.detail, status = EXCLUDED.status, detected_on = EXCLUDED.detected_on;

INSERT INTO consistency_findings (consistency_finding_id, rule, domain, detail, status, detected_on)
VALUES ('cr-15-10', 'cr-15', 'domain-legacy-runner', 'postgres/01-drop-and-create-tables.sql is emitted in check-add mode (CREATE TABLE IF NOT EXISTS, no DROP) even with -p drop_all=true, so init-db.sh does not regenerate erb_admin_portal from scratch: renamed PKs left 8 stale RulebookDomains and 26 stale ClaudeSkills rows. A fresh DB (dropdb + init-db) is required after any PK rename until the transpiler honors drop_all.', 'open', '2026-08-30') ON CONFLICT (consistency_finding_id) DO UPDATE SET rule = EXCLUDED.rule, domain = EXCLUDED.domain, detail = EXCLUDED.detail, status = EXCLUDED.status, detected_on = EXCLUDED.detected_on;

INSERT INTO consistency_findings (consistency_finding_id, rule, domain, detail, status, detected_on)
VALUES ('cr-15-11', 'cr-15', NULL, 'rulebook-to-postgres translates {{X}} <> "" to NULLIF(x, '''') IS NOT NULL; wrapping the reference in COALESCE({{X}}, "") therefore makes every blank-check always true. Thirty formulas were authored with the wrapper and rewritten to the bare idiom.', 'fixed', '2026-08-30') ON CONFLICT (consistency_finding_id) DO UPDATE SET rule = EXCLUDED.rule, domain = EXCLUDED.domain, detail = EXCLUDED.detail, status = EXCLUDED.status, detected_on = EXCLUDED.detected_on;

INSERT INTO consistency_findings (consistency_finding_id, rule, domain, detail, status, detected_on)
VALUES ('cr-15-12', 'cr-15', NULL, 'Rule cr-01 originally demanded <slug>-rulebook.json only; corrected to accept effortless-rulebook.json as well (both valid, protocol-neutral). Findings cr-01-01/04/05 (causal-autoimmune-architecture, lazr-coulombs-law, turek-hitchens) were withdrawn. Follow-up: the effortless-skills suite should state the same.', 'fixed', '2026-08-30') ON CONFLICT (consistency_finding_id) DO UPDATE SET rule = EXCLUDED.rule, domain = EXCLUDED.domain, detail = EXCLUDED.detail, status = EXCLUDED.status, detected_on = EXCLUDED.detected_on;

INSERT INTO consistency_findings (consistency_finding_id, rule, domain, detail, status, detected_on)
VALUES ('cr-15-13', 'cr-15', NULL, 'rulebook-to-postgres emits IF expressions used as boolean predicates inside AND/OR as text, causing live view failure. ProjectSlotWitnesses formulas were rewritten as boolean AND/OR expressions with IF only producing numeric/string results.', 'fixed', '2026-08-30') ON CONFLICT (consistency_finding_id) DO UPDATE SET rule = EXCLUDED.rule, domain = EXCLUDED.domain, detail = EXCLUDED.detail, status = EXCLUDED.status, detected_on = EXCLUDED.detected_on;

