-- ----------------------------------------------------------------------------
-- CMCCSummary: One-line CMCC framing for the platform rulebook itself: what it is, what it generates, and what conformance it claims.
-- ----------------------------------------------------------------------------
INSERT INTO cmcc_summary (cmcc_summary_id, name, description)
VALUES ('primary', 'primary', 'Top-level rulebook describing the ERB project itself: rulebook-as-hub SSoT, ssotme-proxy (10+ substrate routes), admin portal (Viewer/Developer roles, navigation, screens, APIs, write-through invariant), AppUsers + permissions, build pipeline, conformance testing.') ON CONFLICT (cmcc_summary_id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description;

-- ----------------------------------------------------------------------------
-- ProjectGoal: The primary goal of the platform: the load-bearing claim the project is built to demonstrate.
-- ----------------------------------------------------------------------------
INSERT INTO project_goal (project_goal_id, name, description)
VALUES ('primary', 'primary', 'Demonstrate that a single declarative rulebook (effortless-rulebook.json) can generate working, conformant code in 10+ execution substrates that all produce identical results — AND that the developer experience on top of it (the admin portal) is itself driven entirely by rulebook entities (navigation, roles, screens, permissions, users).') ON CONFLICT (project_goal_id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description;

-- ----------------------------------------------------------------------------
-- ArchitecturalHighlight: The architectural pattern that makes the platform work: input spokes write to the rulebook, output spokes read from it, conformance binds them.
-- ----------------------------------------------------------------------------
INSERT INTO architectural_highlight (architectural_highlight_id, name, description)
VALUES ('primary', 'primary', 'effortless-rulebook.json is the DURABLE SSoT. Input spokes (admin portal, Airtable, LLM, manual JSON) all write into it. Output spokes (Python, Go, Postgres, Excel, OWL, PlantUML, Explain-DAG, English, COBOL, ARM64, Entity Framework, Airtable reverse-sync) all read from it. Every substrate passes the same conformance tests.') ON CONFLICT (architectural_highlight_id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description;

